const csvRaw = $json.data ?? $json.body ?? $json;
const text = typeof csvRaw === "string"
  ? csvRaw
  : JSON.stringify(csvRaw);

const lines = text
  .split(/\r?\n/)
  .map(line => line.trim())
  .filter(Boolean);

if (lines.length === 0) {
  return [{ json: { investimentos: [] } }];
}

const headers = lines[0].split(",").map(header => header.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(col => col.trim());
  const obj = {};

  headers.forEach((header, i) => {
    obj[header] = cols[i] ?? "";
  });

  // Normaliza o campo minimo para número
  obj.minimo = Number(
    String(obj.minimo).replace(/[^\d]/g, "")
  ) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// Função auxiliar para selecionar um item aleatório de uma lista (pick)
function pick(arr) {
  if (!arr || arr.length === 0) return "";
  return arr[Math.floor(Math.random() * arr.length)];
}

// Função auxiliar para converter saldo formatado (ex: "R$ 15.000,00" ou "15000.0") em Number
function parseSaldo(saldoVal) {
  if (typeof saldoVal === 'number') return saldoVal;
  if (!saldoVal) return 0;

  // Remove R$, espaços e converte formato pt-BR para float
  const limpo = String(saldoVal)
    .replace(/[^\d,.-]/g, '')
    .replace(/\./g, '')
    .replace(',', '.');

  const num = parseFloat(limpo);
  return isNaN(num) ? 0 : num;
}

// 1. Captura a lista de clientes enviada pelo nó Webhook
const payloadWebhook = $('Webhook').first().json;
const clientes = payloadWebhook.body?.clientes || payloadWebhook.clientes || [];

// 2. Captura os dados de investimento lidos do CSV (ajuste o nome do nó se necessário)
let investimentos = [];
try {
  investimentos = $('Parse CSV').all().map(item => item.json);
} catch (e) {
  // Fallback caso o nó do CSV tenha outro nome no seu fluxo
  try {
    investimentos = $('HTTP Request').all().map(item => item.json);
  } catch (err) {
    investimentos = [];
  }
}

// 3. Processamento de cada cliente
const resultados = clientes.map(c => {
  const nome = c.nome || "Cliente";
  const email = c.email || "";
  const perfil = c.perfil || "Conservador";
  const saldoNum = parseSaldo(c.saldo);
  const saldoTexto = typeof c.saldo === 'number' 
    ? `R$ ${c.saldo.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`
    : (c.saldo || "R$ 0,00");

  // Filtra as opções de investimento correspondentes ao perfil do cliente
  const opcoesPerfil = investimentos.filter(inv => {
    const perfilInv = (inv.perfil || inv.Perfil || "").toLowerCase();
    return perfilInv === perfil.toLowerCase();
  });

  // Seleciona a recomendação ideal
  let escolhido = null;
  let motivo = "";

  if (opcoesPerfil.length > 0) {
    // Escolhe a opção dentro do perfil (priorizando as que se adequam ao saldo)
    escolhido = opcoesPerfil[0]; // Pega a primeira opção disponível do perfil
    motivo = `Opção alinhada ao seu perfil ${perfil} para otimizar seus rendimentos.`;
  } else {
    // Caso não encontre no CSV, usa um padrão do Santander
    escolhido = {
      produto: perfil.toLowerCase() === 'arrojado' ? 'Ações Santander IBOV' : (perfil.toLowerCase() === 'moderado' ? 'Fundo Multimercado Santander' : 'CDB Santander 100% CDI'),
      retorno_esperado: perfil.toLowerCase() === 'arrojado' ? 'Variável' : '100% CDI',
      nivel_risco: perfil.toLowerCase() === 'arrojado' ? 'Alto' : (perfil.toLowerCase() === 'moderado' ? 'Médio' : 'Baixo')
    };
    motivo = `Recomendação padrão Santander para o perfil ${perfil}.`;
  }

  // Gera opções de mensagens estáticas (MVP)
  const produtoNome = escolhido.produto || escolhido.Produto || "CDB Santander";
  const mensagens = [
    `Olá ${nome}, vimos que seu perfil é ${perfil}. Com seu saldo de ${saldoTexto}, recomendamos investir em ${produtoNome}.`,
    `Oi ${nome}! Para seu perfil ${perfil}, a melhor oportunidade atual é ${produtoNome}. Rentabilize seu saldo de ${saldoTexto}!`,
    `Prezado(a) ${nome}, com base na sua estratégia ${perfil}, indicamos a aplicação em ${produtoNome}.`
  ];

  return {
    nome,
    email,
    perfil,
    saldo_texto: saldoTexto,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens)
  };
});

// 4. Retorno final exatamente na estrutura esperada pelo seu fluxo n8n (conforme o print)
return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados: resultados
  }
}];

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// retorna UM ITEM por cliente
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao || {},
      motivo: c.motivo || "saldo_ok",
      mensagem_base: c.mensagem_escolhida || (Array.isArray(c.mensagens) ? c.mensagens[0] : "") || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: [
          "promessas de ganho",
          "garantias",
          "linguagem agressiva"
        ]
      }
    }
  };
});

return out;

return $input.all().map((item, index) => {
  // 1. Pega os dados do cliente do nó anterior
  let j = {};
  try {
    j = $('Code in JavaScript2').all()[index]?.json || {};
  } catch (e) {
    j = {};
  }

  // 2. Localiza a string de texto retornada pelo nó (Message a model)
  const rawText = 
    item.json.output?.[0]?.content?.[0]?.text || 
    item.json.text || 
    item.json.output || 
    "";

  // 3. Limpa marcações markdown de bloco ```json do modelo
  const cleanJson = String(rawText)
    .replace(/```json/gi, "")
    .replace(/```/gi, "")
    .trim();

  // 4. Converte a string JSON em objeto
  let parsed = {};
  try {
    parsed = JSON.parse(cleanJson);
  } catch (err) {
    parsed = {};
  }

  // 5. Monta as variáveis
  const to = j.email_to || j.email || "";
  const subject = parsed.subject || "";
  const text_body = parsed.text_body || rawText;
  const html_body = parsed.html_body || (text_body ? `<p>${text_body.replace(/\n/g, "<br>")}</p>` : "");

  // 6. Retorno
  return {
    json: {
      ok: true,
      to,
      subject,
      text_body,
      html_body,

      // (opcional) manter alguns campos úteis pra debug/aula
      meta: {
        nome: j.nome,
        perfil: j.perfil,
        produto: j.recomendacao?.produto,
        minimo: j.recomendacao?.minimo,
        rentabilidade: j.recomendacao?.rentabilidade || j.recomendacao?.retorno_esperado,
        motivo: j.motivo
      }
    }
  };
});

